  function validateSubjects(rows){const allowed=controlledSubjects(),seen=new Set();if(!rows?.length)throw new Error('Add at least one tutoring subject.');return rows.map(row=>{const subjectId=String(row.subjectId||''),courseLevel=String(row.courseLevel||''),resultType=String(row.claimedResultType||''),value=String(row.claimedResultValue||'').trim(),summary=String(row.qualificationSummary||'').trim();if(!allowed.has(subjectId))throw new Error('Choose a subject from the active catalogue.');if(!COURSE_LEVELS.includes(courseLevel))throw new Error('Choose a supported course level.');if(!RESULT_TYPES.includes(resultType))throw new Error('Choose a supported qualification result type.');if(!value&&!summary)throw new Error('Add a relevant result or qualification explanation for each subject.');if(value.length>80||summary.length>300||contactPattern.test(summary))throw new Error('Qualification information is invalid or contains private contact information.');const key=`${subjectId}|${courseLevel}`;if(seen.has(key))throw new Error('Duplicate subject and course-level combinations are not allowed.');seen.add(key);return {id:row.id||uid('application-subject'),subjectId,courseLevel,qualificationType:String(row.qualificationType||'COURSE_RESULT').slice(0,50),claimedResultType:resultType,claimedResultValue:value.slice(0,80),qualificationSummary:summary.slice(0,300),createdAt:row.createdAt||now(),updatedAt:now()};});}
