  const ALLOWED={NOT_APPLIED:['APPLICATION_INCOMPLETE'],APPLICATION_INCOMPLETE:['PENDING_VERIFICATION'],PENDING_VERIFICATION:['VERIFIED','CHANGES_REQUESTED','REJECTED','SUSPENDED'],CHANGES_REQUESTED:['PENDING_VERIFICATION','SUSPENDED'],VERIFIED:['CHANGES_REQUESTED','SUSPENDED'],REJECTED:['APPLICATION_INCOMPLETE'],SUSPENDED:['PENDING_VERIFICATION','VERIFIED']};
