  function suspendTutor(tutorUserId,input){const actor=current();P.requireRole(actor,P.ROLES.PLATFORM_ADMIN);const app=applications().find(a=>a.tutorUserId===tutorUserId);if(!app||!SUSPENSION_CATEGORIES.includes(input.category))throw new Error('A valid tutor and suspension category are required.');const notice=validateText(input.applicantVisibleComment,10,600,'Suspension notice',{allowContact:true});const previous=app.status;app.suspensionCategory=input.category;transition(app,TUTOR_STATUS.SUSPENDED,actor,{category:input.category,applicantVisibleComment:notice,internalNote:input.internalNote});app.previousStatusBeforeSuspension=previous;revokeCapabilities(tutorUserId,actor,'SUSPENDED');audit(actor,'TUTOR_SUSPENDED','TutorApplication',app.id,{category:input.category});notifyUser(tutorUserId,'Your tutoring access is currently suspended.','TUTOR_APPLICATION');return app;}
  function reinstateTutor(tutorUserId,input){const actor=current();P.requireRole(actor,P.ROLES.PLATFORM_ADMIN);const app=applications().find(a=>a.tutorUserId===tutorUserId);if(!app||app.status!==TUTOR_STATUS.SUSPENDED)throw new Error('Only a suspended tutor can be reinstated.');const next=input.nextStatus===TUTOR_STATUS.VERIFIED&&capabilities().some(c=>c.tutorUserId===tutorUserId&&c.revokedAt)?TUTOR_STATUS.PENDING_VERIFICATION:(input.nextStatus||TUTOR_STATUS.PENDING_VERIFICATION);transition(app,next,actor,{category:'REINSTATED',applicantVisibleComment:'Your tutor status has been reinstated for review.'});audit(actor,'TUTOR_REINSTATED','TutorApplication',app.id,{nextStatus:next});notifyUser(tutorUserId,'Your tutor status was reinstated.','TUTOR_APPLICATION');return app;}
