  function reviewerQueue(actor=current()){if(!isReviewer(actor))return [];if(P.hasRole(actor,P.ROLES.PLATFORM_ADMIN))return applications();const orgs=peerData(actor).organizationMemberships.filter(m=>m.authorizationStatus===P.VERIFIER_STATUS.ACTIVE).map(m=>m.organizationId);return applications().filter(app=>orgs.includes(app.organizationId));}
  function sanitizeFileName(name){return String(name||'document').replace(/[^\p{L}\p{N}._ -]/gu,'_').replace(/\.{2,}/g,'.').slice(0,120)||'document';}
