  function uploadDocument(file,category='OTHER'){const actor=current(),app=requireOwnerEditable(getApplication(actor),actor);validateDocument(file);const currentDocs=documents().filter(d=>d.tutorApplicationId===app.id&&!d.deletedAt);if(currentDocs.length>=MAX_FILES||currentDocs.reduce((n,d)=>n+d.fileSize,0)+file.size>MAX_TOTAL_SIZE)throw new Error('The application document limit has been reached.');const doc={id:uid('tutor-document'),tutorApplicationId:app.id,uploadedByUserId:actor.id,documentCategory:String(category).slice(0,50),storageKey:`private/tutor-applications/${app.id}/${uid('object')}`,sanitizedFileName:sanitizeFileName(file.name),mimeType:file.type,fileSize:file.size,checksum:file.checksum||null,scanStatus:'QUARANTINED',uploadedAt:now(),replacedAt:null,deletedAt:null};documents().push(doc);audit(actor,'TUTOR_DOCUMENT_UPLOADED','TutorSupportingDocument',doc.id,{applicationId:app.id,documentId:doc.id});persist();return privateDocumentMetadata(doc);}
