  function canViewDocument(actor,doc){const app=applications().find(a=>a.id===doc?.tutorApplicationId);return Boolean(doc&&!doc.deletedAt&&app&&canView(actor,app));}
  function getDocumentAccess(docId,purpose='VIEW'){const actor=current(),doc=documents().find(d=>d.id===docId);if(!canViewDocument(actor,doc)){if(actor)audit(actor,'TUTOR_DOCUMENT_ACCESS_DENIED','TutorSupportingDocument',docId,{purpose});throw new Error('You do not have access to this supporting document.');}if(doc.scanStatus!=='CLEAN'&&actor.id!==doc.uploadedByUserId)throw new Error('This document is not available until security review is complete.');const app=applications().find(a=>a.id===doc.tutorApplicationId);audit(actor,purpose==='DOWNLOAD'?'TUTOR_DOCUMENT_DOWNLOADED':'TUTOR_DOCUMENT_VIEWED','TutorSupportingDocument',doc.id,{applicationId:app.id,documentId:doc.id,organizationId:app.organizationId,accessReason:purpose});return {document:privateDocumentMetadata(doc),authorizationToken:uid('short-lived-access'),expiresAt:new Date(Date.now()+5*60*1000).toISOString()};}
