  function activeCapabilities(tutorUserId){return capabilities().filter(c=>c.tutorUserId===tutorUserId&&!c.revokedAt);}
  function matchingBlockers(a){const app=getApplication(a),base=[];if(!app||app.status!==TUTOR_STATUS.VERIFIED)base.push('TUTOR_NOT_VERIFIED');if(peerData(a).accountStatus!==P.ACCOUNT_STATUS.ACTIVE)base.push('ACCOUNT_SUSPENDED');if(!P.hasRole(a,P.ROLES.PEER_TUTOR))base.push('ROLE_REQUIRED');if(!S.isEmailVerified(a))base.push('EMAIL_NOT_VERIFIED');if(!S.isStudentProfileComplete(a))base.push('PROFILE_INCOMPLETE');if(S.requiresGuardianConsent(a)&&!S.hasActiveGuardianConsent(a))base.push('GUARDIAN_CONSENT_REQUIRED');if(!app||app.codeOfConductVersion!==CODE_OF_CONDUCT_VERSION||!app.codeOfConductAgreedAt)base.push('CODE_OF_CONDUCT_OUTDATED');if(!activeCapabilities(a.id).length)base.push('NO_APPROVED_CAPABILITIES');if(!S.getStudentProfile(a).availableForTutoring)base.push('TUTOR_UNAVAILABLE');if(a.safetyRestriction===true)base.push('SAFETY_RESTRICTION');if(a.organizationRestriction===true)base.push('ORGANIZATION_RESTRICTION');return unique(base);}
  const canAppearInMatching=a=>matchingBlockers(a).length===0;
  function getVerifiedCandidates(filters={}){return allUsers().filter(a=>canAppearInMatching(a)).filter(a=>{const caps=activeCapabilities(a.id);return (!filters.subjectId||caps.some(c=>c.subjectId===filters.subjectId))&&(!filters.gradeLevel||caps.some(c=>c.gradeLevels.includes(filters.gradeLevel)))&&(!filters.languageCode||caps.some(c=>c.languageCodes.includes(filters.languageCode)));}).map(toMatchingRecord);}
  function toMatchingRecord(a){return {...S.toPublicStudentProfile(a),tutorStatus:TUTOR_STATUS.VERIFIED,approvedCapabilities:activeCapabilities(a.id).map(c=>({subjectId:c.subjectId,courseLevel:c.courseLevel,gradeLevels:[...c.gradeLevels],languageCodes:[...c.languageCodes],sessionModePreference:c.sessionModePreference}))};}
