  let activeStep='status',reviewMode=false,selectedReviewId=null;
  function badge(status){return `<span class="tutor-app-status" data-status="${status}"><span aria-hidden="true">●</span> ${safe(STATUS_LABELS[status]||status)}</span>`;}
  function progress(app){const p=getProgress(app,current());return `<div class="tutoring-completion"><div><b>Application progress</b><span>${p.percentage}%</span></div><progress value="${p.percentage}" max="100">${p.percentage}%</progress></div>`;}
  function nav(){return `<ol class="tutor-app-stepper" aria-label="Tutor application sections">${APP_STEPS.map((s,i)=>`<li class="${s===activeStep?'active':''}"><button type="button" data-app-step="${s}"><span>${i+1}</span>${safe(STEP_LABELS[s])}</button></li>`).join('')}</ol>`;}
  function appShell(app,body){return `${nav()}<section class="card tutor-app-summary"><div><span class="kicker">PRIVATE APPLICATION</span><h2>${badge(app.status)}</h2></div>${progress(app)}</section>${body}`;}
  function controls(next,back){return `<div class="student-form-actions">${back?`<button class="btn btn-secondary" data-app-step="${back}" type="button">Back</button>`:''}<button class="btn btn-secondary" data-save-tutor-exit type="button">Save and exit</button>${next?`<button class="btn btn-primary" type="submit" data-next="${next}">Save and continue</button>`:''}</div>`;}
  function subjectsForm(app){const row=app.subjects[0]||{},grades=new Set(app.supportedGradeLevels);return `<form class="card tutor-application-form" id="tutorSubjectsForm"><h2>Subjects and qualifications</h2><p>Exact marks and qualification evidence remain private.</p><div class="form-row"><label>Subject<select name="subjectId">${catalogue().map(c=>`<option ${c===row.subjectId?'selected':''}>${safe(c)}</option>`).join('')}</select></label><label>Course level<select name="courseLevel">${COURSE_LEVELS.map(c=>`<option ${c===row.courseLevel?'selected':''}>${safe(c)}</option>`).join('')}</select></label></div><div class="form-row"><label>Result type<select name="claimedResultType">${RESULT_TYPES.map(c=>`<option value="${c}" ${c===row.claimedResultType?'selected':''}>${safe(c.replaceAll('_',' '))}</option>`).join('')}</select></label><label>Result or credential<input name="claimedResultValue" value="${safe(row.claimedResultValue||'')}" maxlength="80"></label></div><label>Qualification explanation<textarea name="qualificationSummary" maxlength="300">${safe(row.qualificationSummary||'')}</textarea></label><fieldset><legend>Grade levels you can support</legend><div class="student-check-grid">${S.GRADES.map(g=>`<label><input type="checkbox" name="gradeLevels" value="${g}" ${grades.has(g)?'checked':''}> ${g}</label>`).join('')}</div></fieldset>${controls('experience','')}</form>`;}
  function experienceForm(app){const e=app.experienceEntries[0]||{};return `<form class="card tutor-application-form" id="tutorExperienceForm"><h2>Relevant experience</h2><p>Prior tutoring is not required. Do not include private contact information or confidential student information.</p><label class="tutoring-check"><input type="checkbox" name="none" ${app.noPreviousExperience?'checked':''}> I have no previous tutoring or leadership experience</label><div class="form-row"><label>Experience type<select name="experienceType">${EXPERIENCE_TYPES.filter(x=>x!=='NONE').map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Role<input name="role" value="${safe(e.role||'')}" maxlength="100"></label></div><label>Short description<textarea name="description" maxlength="500">${safe(e.description||'')}</textarea></label><label>Overall experience summary<textarea name="summary" maxlength="800">${safe(app.previousExperienceSummary||'')}</textarea></label>${controls('languages','subjects')}</form>`;}
  function languagesForm(app){const chosen=app.languages[0]?.languageCode||'en';return `<form class="card tutor-application-form" id="tutorLanguagesForm"><h2>Tutoring languages</h2><label>Language<select name="languageCode">${S.LANGUAGES.map(l=>`<option value="${l.code}" ${l.code===chosen?'selected':''}>${safe(l.label)}</option>`).join('')}</select></label><label>Comfort level<select name="proficiencyLevel"><option>Comfortable</option><option>Fluent</option><option>Native or bilingual</option></select></label>${controls('availability','experience')}</form>`;}
  function availabilityForm(app){return `<form class="card tutor-application-form" id="tutorAvailabilityForm"><h2>Weekly tutor availability</h2><label class="tutoring-check"><input type="checkbox" name="reuse" checked> Reuse my general student availability</label><label class="tutoring-check"><input type="checkbox" name="varies" ${app.availabilityVaries?'checked':''}> My availability varies</label><fieldset><legend>Session preference</legend><div class="student-radio-grid">${S.SESSION_MODES.map(m=>`<label><input type="radio" name="sessionModePreference" value="${m}" ${m===(app.sessionModePreference||'ONLINE')?'checked':''}> ${m.replaceAll('_',' ')}</label>`).join('')}</div></fieldset><div class="tutoring-separation">Do not enter your home address. In-person sessions must use approved school, library, community, or public locations.</div>${controls('motivation','languages')}</form>`;}
  function motivationForm(app){return `<form class="card tutor-application-form" id="tutorMotivationForm"><h2>Why do you want to become a peer tutor?</h2><p>Describe your strengths and approach without sharing contact details or sensitive personal information.</p><label>Motivation statement<textarea name="motivation" minlength="80" maxlength="1200" rows="8" required>${safe(app.motivationStatement||'')}</textarea></label>${controls('conduct','availability')}</form>`;}
  function conductForm(app){return `<form class="card tutor-application-form" id="tutorConductForm"><h2>Tutor code of conduct</h2><p>Version ${CODE_OF_CONDUCT_VERSION}</p><ul><li>Protect student privacy and communicate only through approved platform channels.</li><li>Use respectful, inclusive, and age-appropriate language.</li><li>Teach honestly and never complete assessed work for another student.</li><li>Report safety concerns through approved processes.</li><li>Use approved public or organization locations for in-person sessions.</li></ul><label class="tutoring-check"><input type="checkbox" name="agree"> I have read and explicitly agree to the current tutor code of conduct.</label>${controls('documents','motivation')}</form>`;}
  function documentsView(app){const docs=documents().filter(d=>d.tutorApplicationId===app.id&&!d.deletedAt);return `<div class="card tutor-application-form"><h2>Optional supporting documents</h2><p>Supporting documents are private. They are available only to you, authorized application verifiers, and platform administrators.</p><p class="prototype-notice"><b>Local prototype limitation:</b> this build stores private document metadata only. It does not upload document bytes or create public URLs.</p><form id="tutorDocumentForm"><div class="form-row"><label>Document category<select name="category"><option>COURSE_RECORD</option><option>CERTIFICATE</option><option>AWARD</option><option>RECOMMENDATION</option><option>OTHER</option></select></label><label>Choose PDF, JPEG, or PNG<input name="document" type="file" accept="application/pdf,image/jpeg,image/png"></label></div><button class="btn btn-secondary" type="submit">Add private document metadata</button></form><div class="private-document-list">${docs.length?docs.map(d=>`<div><b>${safe(d.sanitizedFileName)}</b><span>${safe(d.scanStatus)} · ${Math.ceil(d.fileSize/1024)} KB</span><button class="btn btn-danger" data-delete-tutor-document="${d.id}" type="button">Remove</button></div>`).join(''):'<p>No supporting documents added. Documents are optional.</p>'}</div>${controls('review','conduct')}</div>`;}
  function reviewView(app){const p=getProgress(app,current()),latest=latestSubmission(app);return `<div class="card tutor-application-form"><h2>Review and submit</h2><p><b>Missing requirements:</b> ${p.missingRequirements.length?safe(p.missingRequirements.map(x=>x.replaceAll('_',' ')).join(', ')):'None'}</p><div class="tutor-review-summary"><p><b>Subjects:</b> ${safe(app.subjects.map(s=>`${s.subjectId} — ${s.courseLevel}`).join(', ')||'Not added')}</p><p><b>Grade levels:</b> ${safe(app.supportedGradeLevels.join(', ')||'Not added')}</p><p><b>Languages:</b> ${safe(app.languages.map(l=>l.languageCode).join(', ')||'Not added')}</p><p><b>Code of conduct:</b> ${app.codeOfConductVersion===CODE_OF_CONDUCT_VERSION?'Accepted':'Required'}</p><p><b>Email:</b> ${S.isEmailVerified(current())?'Verified':'Verification required'}</p><p><b>Guardian consent:</b> ${S.requiresGuardianConsent(current())?(S.hasActiveGuardianConsent(current())?'Granted':'Required'):'Not required'}</p><p><b>Submitted versions:</b> ${app.submissions.length}${latest?` · Latest version ${latest.version}`:''}</p></div><div class="tutoring-separation">Application details, exact marks, supporting documents, reviewer notes, guardian information, and private learning-support preferences are never part of the public tutor profile.</div><div class="student-form-actions"><button class="btn btn-secondary" data-app-step="documents" type="button">Back</button><button class="btn btn-primary" id="submitTutorApplication" type="button" ${p.canSubmit?'':'disabled'}>${app.status===TUTOR_STATUS.CHANGES_REQUESTED?'Resubmit application':'Submit for verification'}</button></div></div>`;}
  function statusView(app){const p=getProgress(app,current()),caps=activeCapabilities(app.tutorUserId),changes=changeRequests().filter(r=>r.tutorApplicationId===app.id&&!r.resolvedAt);const messages={NOT_APPLIED:'Start your tutor application to be considered for the peer-tutoring program.',APPLICATION_INCOMPLETE:'Your application has been saved but is not ready for review.',PENDING_VERIFICATION:'Your application has been submitted and is awaiting review.',VERIFIED:'Your tutor application has been verified.',CHANGES_REQUESTED:'Changes are required before your application can be reviewed again.',REJECTED:'Your application was not approved.',SUSPENDED:'Your tutoring access is currently suspended.'};return `<div class="card tutor-application-form tutor-status-page"><h2>${badge(app.status)}</h2><p>${safe(messages[app.status])}</p>${app.status===TUTOR_STATUS.APPLICATION_INCOMPLETE?`<p>${p.percentage}% complete · ${safe(p.missingRequirements.join(', '))}</p><button class="btn btn-primary" data-app-step="subjects">Continue application</button>`:''}${app.status===TUTOR_STATUS.PENDING_VERIFICATION?`<p>Submitted ${safe(app.submittedAt||'')} · Version ${app.currentVersion}</p>`:''}${app.status===TUTOR_STATUS.VERIFIED?`<h3>Approved capabilities</h3>${caps.map(c=>`<p>${safe(c.subjectId)} · ${safe(c.courseLevel)} · ${safe(c.gradeLevels.join(', '))}</p>`).join('')||'<p>No active capabilities. You remain unavailable for matching.</p>'}<p><b>Matching blockers:</b> ${safe(matchingBlockers(current()).join(', ')||'None')}</p>`:''}${app.status===TUTOR_STATUS.CHANGES_REQUESTED?`${changes.map(c=>`<p><b>${safe(c.category)}</b>: ${safe(c.applicantVisibleInstruction)}</p>`).join('')}<button class="btn btn-primary" data-app-step="subjects">Revise application</button>`:''}${[TUTOR_STATUS.REJECTED,TUTOR_STATUS.SUSPENDED].includes(app.status)?`<p>${safe(app.applicantVisibleDecisionComment||'Contact the program through its approved support process for more information.')}</p>`:''}</div>`;}
  function renderApplicant(){const root=document.querySelector('#tutorApplicationContent'),a=current();if(!root)return;if(!a){root.innerHTML='<div class="empty-state card"><h2>Sign in required</h2></div>';return;}if(!P.hasRole(a,P.ROLES.PEER_TUTOR)){root.innerHTML='<div class="empty-state card"><h2>Peer Tutor role required</h2><p>Request the Peer Tutor role from the role setup page first.</p></div>';return;}let app=getApplication(a);if(!app||app.status===TUTOR_STATUS.NOT_APPLIED){root.innerHTML=`<div class="card tutor-status-page"><h2>${badge(TUTOR_STATUS.NOT_APPLIED)}</h2><p>Start your tutor application to be considered for the peer-tutoring program.</p><button class="btn btn-primary" id="startTutorApplication">Start application</button></div>`;bind(root);return;}if(reviewMode){renderQueue(root);return;}const editable=[TUTOR_STATUS.APPLICATION_INCOMPLETE,TUTOR_STATUS.CHANGES_REQUESTED].includes(app.status),views={subjects:()=>subjectsForm(app),experience:()=>experienceForm(app),languages:()=>languagesForm(app),availability:()=>availabilityForm(app),motivation:()=>motivationForm(app),conduct:()=>conductForm(app),documents:()=>documentsView(app),review:()=>reviewView(app),status:()=>statusView(app)};if(!editable&&!['status'].includes(activeStep))activeStep='status';root.innerHTML=appShell(app,views[activeStep]());bind(root);}
  function renderQueue(root){const actor=current(),queue=reviewerQueue(actor);if(!isReviewer(actor)){root.innerHTML='<div class="empty-state card"><h2>Review access required</h2><p>Only active organization verifiers and platform administrators can view this queue.</p></div>';return;}const selected=selectedReviewId?queue.find(a=>a.id===selectedReviewId):null;if(selected){const data=privateApplication(selected,actor),submission=latestSubmission(selected);root.innerHTML=`<button class="btn btn-secondary" id="backTutorReviewQueue">Back to queue</button><div class="card tutor-review-detail"><h2>${safe(data.applicantName)} · ${badge(data.status)}</h2><p>Submitted version ${submission?.version||'—'}</p><p><b>Subjects:</b> ${safe((submission?.submittedSnapshot.subjects||[]).map(s=>`${s.subjectId} — ${s.courseLevel}`).join(', '))}</p><p><b>Grade levels:</b> ${safe((submission?.submittedSnapshot.supportedGradeLevels||[]).join(', '))}</p><p><b>Languages:</b> ${safe((submission?.submittedSnapshot.languages||[]).map(l=>l.languageCode).join(', '))}</p><p><b>Motivation:</b> ${safe(submission?.submittedSnapshot.motivationStatement||'')}</p><p><b>Documents:</b> ${data.documents.length} private document(s); contents are not shown in queue previews.</p><div class="tutor-review-actions"><button class="btn btn-primary" data-review-decision="verify">Verify</button><button class="btn btn-secondary" data-review-decision="changes">Request changes</button><button class="btn btn-danger" data-review-decision="reject">Reject</button></div><form id="tutorReviewDecisionForm" class="hidden"><label>Applicant-visible explanation<textarea name="comment" maxlength="1000" required></textarea></label><label>Internal note (reviewers only)<textarea name="internalNote" maxlength="1500"></textarea></label><div id="tutorReviewExtra"></div><label class="tutoring-check"><input type="checkbox" name="confirm" required> I confirm this decision and that I have no prohibited conflict of interest.</label><button class="btn btn-primary" type="submit">Submit protected decision</button></form></div>`;bind(root);return;}root.innerHTML=`<div class="card tutor-review-queue"><h2>Tutor application review queue</h2><p>Applications are limited to your authorized organization scope.</p><div class="tutoring-table-wrap"><table><thead><tr><th>Applicant</th><th>Status</th><th>Version</th><th>Submitted</th><th></th></tr></thead><tbody>${queue.map(app=>{const owner=allUsers().find(u=>u.id===app.tutorUserId);return `<tr><td>${safe(owner?.name||'Applicant')}</td><td>${badge(app.status)}</td><td>${app.currentVersion}</td><td>${safe(app.submittedAt||'—')}</td><td><button class="btn btn-secondary" data-open-review="${app.id}">Review</button></td></tr>`}).join('')||'<tr><td colspan="5">No applications in this authorized queue.</td></tr>'}</tbody></table></div></div>`;bind(root);}
  function formValues(form){return Object.fromEntries(new FormData(form).entries());}
  function go(step){if(APP_STEPS.includes(step)){activeStep=step;renderApplicant();}}
  function showError(err){if(typeof toast==='function')toast(err.message||'The action could not be completed.');}
  function saved(message='Application saved.'){if(typeof toast==='function')toast(message);renderApplicant();}
  function bind(root){
    root.querySelector('#startTutorApplication')?.addEventListener('click',()=>{try{startApplication();activeStep='subjects';saved('Tutor application started.')}catch(e){showError(e)}});
    root.querySelectorAll('[data-app-step]').forEach(b=>b.onclick=()=>go(b.dataset.appStep));root.querySelectorAll('[data-save-tutor-exit]').forEach(b=>b.onclick=()=>{saved();showView('peerTutoring')});
    root.querySelector('#tutorSubjectsForm')?.addEventListener('submit',e=>{e.preventDefault();const v=formValues(e.target);try{saveSubjects({subjects:[v],gradeLevels:new FormData(e.target).getAll('gradeLevels')});go('experience')}catch(x){showError(x)}});
    root.querySelector('#tutorExperienceForm')?.addEventListener('submit',e=>{e.preventDefault();const v=formValues(e.target),none=e.target.elements.none.checked,has=v.description?.trim();try{saveExperience({noPreviousExperience:none,entries:!none&&has?[v]:[],summary:v.summary});go('languages')}catch(x){showError(x)}});
    root.querySelector('#tutorLanguagesForm')?.addEventListener('submit',e=>{e.preventDefault();const v=formValues(e.target);try{saveLanguages({languages:[{...v,canTutorInLanguage:true}]});go('availability')}catch(x){showError(x)}});
    root.querySelector('#tutorAvailabilityForm')?.addEventListener('submit',e=>{e.preventDefault();const v=formValues(e.target);try{saveAvailability({reuseStudent:e.target.elements.reuse.checked,availabilityVaries:e.target.elements.varies.checked,sessionModePreference:v.sessionModePreference});go('motivation')}catch(x){showError(x)}});
    root.querySelector('#tutorMotivationForm')?.addEventListener('submit',e=>{e.preventDefault();try{saveMotivation(formValues(e.target).motivation);go('conduct')}catch(x){showError(x)}});
    root.querySelector('#tutorConductForm')?.addEventListener('submit',e=>{e.preventDefault();try{acceptCodeOfConduct(e.target.elements.agree.checked);go('documents')}catch(x){showError(x)}});
    root.querySelector('#tutorDocumentForm')?.addEventListener('submit',e=>{e.preventDefault();const file=e.target.elements.document.files?.[0],v=formValues(e.target);try{uploadDocument(file,v.category);saved('Private document metadata added.')}catch(x){showError(x)}});
    root.querySelectorAll('[data-delete-tutor-document]').forEach(b=>b.onclick=()=>{try{deleteDocument(b.dataset.deleteTutorDocument);saved('Document removed.')}catch(x){showError(x)}});
    root.querySelector('#submitTutorApplication')?.addEventListener('click',()=>{try{submitApplication();activeStep='status';saved('Tutor application submitted.')}catch(x){showError(x)}});
    root.querySelector('#openTutorReviewQueue')?.addEventListener('click',()=>{reviewMode=true;selectedReviewId=null;renderApplicant()});root.querySelector('#backTutorReviewQueue')?.addEventListener('click',()=>{selectedReviewId=null;renderApplicant()});root.querySelectorAll('[data-open-review]').forEach(b=>b.onclick=()=>{selectedReviewId=b.dataset.openReview;renderApplicant()});
    let decision=null;root.querySelectorAll('[data-review-decision]').forEach(b=>b.onclick=()=>{decision=b.dataset.reviewDecision;const form=root.querySelector('#tutorReviewDecisionForm'),extra=root.querySelector('#tutorReviewExtra');form.classList.remove('hidden');extra.innerHTML=decision==='verify'?`<label>Approved subject<select name="subjectId">${latestSubmission(applications().find(a=>a.id===selectedReviewId))?.submittedSnapshot.subjects.map(s=>`<option>${safe(s.subjectId)}</option>`).join('')}</select></label>`:decision==='changes'?`<label>Change category<select name="category">${CHANGE_CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></label>`:`<label>Rejection category<select name="category">${REJECTION_CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></label>`;});
    root.querySelector('#tutorReviewDecisionForm')?.addEventListener('submit',e=>{e.preventDefault();const v=formValues(e.target),app=applications().find(a=>a.id===selectedReviewId),snap=latestSubmission(app)?.submittedSnapshot,subject=snap?.subjects.find(s=>s.subjectId===v.subjectId)||snap?.subjects[0];try{if(decision==='verify')verifyApplication(app.id,{version:app.currentVersion,confirmVersion:true,evidenceReviewed:true,conductCurrent:true,noConflict:e.target.elements.confirm.checked,applicantVisibleComment:v.comment,internalNote:v.internalNote,capabilities:[{subjectId:subject.subjectId,courseLevel:subject.courseLevel,gradeLevels:snap.supportedGradeLevels,languageCodes:snap.languages.map(l=>l.languageCode)}]});else if(decision==='changes')requestChanges(app.id,{categories:[v.category],applicantVisibleInstruction:v.comment,internalNote:v.internalNote});else rejectApplication(app.id,{category:v.category,applicantVisibleComment:v.comment,internalNote:v.internalNote});saved('Review decision recorded.')}catch(x){showError(x)}});
  }
  function seedDevelopmentData(){if(typeof db==='undefined'||db.tutorApplicationSeeded)return false;S.seedDevelopmentData();const tutors=allUsers().filter(a=>P.hasRole(a,P.ROLES.PEER_TUTOR));const statuses=Object.values(TUTOR_STATUS);tutors.forEach((a,i)=>{let app=getApplication(a);app.status=statuses[i%statuses.length];app.startedAt=app.status===TUTOR_STATUS.NOT_APPLIED?null:now();if(app.status!==TUTOR_STATUS.NOT_APPLIED){app.subjects=[{id:uid('subject'),subjectId:'Biology',courseLevel:'Grade 10',qualificationType:'COURSE_RESULT',claimedResultType:'PERCENTAGE',claimedResultValue:'88',qualificationSummary:'Fake development result.',createdAt:now(),updatedAt:now()}];app.supportedGradeLevels=['Grade 9','Grade 10'];app.languages=[{id:uid('lang'),languageCode:'en',proficiencyLevel:'Fluent',canTutorInLanguage:true,createdAt:now()}];app.noPreviousExperience=true;app.availabilityMode='REUSE_STUDENT';app.motivationStatement='I want to help other students understand difficult ideas by using patient explanations and practical examples in this fake development application.';app.codeOfConductVersion=CODE_OF_CONDUCT_VERSION;app.codeOfConductAgreedAt=now();app.codeOfConductAgreedByUserId=a.id;}syncProjection(app);});db.tutorApplicationSeeded=true;persist();return true;}

  function replaceLegacyTutorForm(){const legacy=document.querySelector('#tutorProfileForm');if(!legacy)return;const card=document.createElement('article');card.className='card tutoring-form';card.innerHTML='<h3>Tutor application</h3><p>The Step 3 application is the canonical place to save qualifications, accept the code of conduct, submit for verification, and track review status.</p><button class="btn btn-primary" type="button">Open Tutor Application</button>';card.querySelector('button').addEventListener('click',()=>showView('tutorApplication'));legacy.replaceWith(card);document.querySelector('#qualificationForm')?.remove();}

  P.isApprovedTutor=a=>Boolean(a&&canonicalTutorStatus(a)===TUTOR_STATUS.VERIFIED&&peerData(a).accountStatus===P.ACCOUNT_STATUS.ACTIVE);
